    avg_iv = float(np.mean(list(invvol.values())))
    raw = {s: max(score[s], 0.01) * (0.78 + 0.22 * invvol.get(s, avg_iv) / max(avg_iv, 1e-12)) for s in UNIVERSE}
    weights = boxed_weights(raw)
    mu = float(np.mean(list(score.values())))
    sd = max(float(np.std(list(score.values()))), 1e-12)
    forecast_returns = {s: float(0.01 * (score[s] - mu) / sd) for s in UNIVERSE}
    rebalance_to_weights(weights, forecast_returns=forecast_returns,
